-- Shiju cloud likes. Run once in the Supabase SQL editor, then run sync-content.sql (generated by build.py).
-- Visitors are Supabase anonymous users; the site only ships the publishable key, so every rule lives here.

-- Valid content ids, mirrored from prompts.json by sync-content.sql. Content itself stays in the static site.
create table if not exists public.content_items (
  id text primary key,
  active boolean not null default true,
  updated_at timestamptz not null default now()
);

-- One row per (content, anonymous user). The primary key is the uniqueness rule and the content_id index.
create table if not exists public.content_likes (
  content_id text not null references public.content_items(id) on delete cascade,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (content_id, user_id)
);
create index if not exists content_likes_user_id_idx on public.content_likes (user_id);

alter table public.content_items enable row level security;
alter table public.content_likes enable row level security;

drop policy if exists "content ids are public" on public.content_items;
create policy "content ids are public" on public.content_items
  for select to anon, authenticated using (true);

drop policy if exists "read own likes" on public.content_likes;
create policy "read own likes" on public.content_likes
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists "like active content as yourself" on public.content_likes;
create policy "like active content as yourself" on public.content_likes
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.content_items c where c.id = content_id and c.active)
  );

drop policy if exists "remove own like" on public.content_likes;
create policy "remove own like" on public.content_likes
  for delete to authenticated using (user_id = (select auth.uid()));

-- Column-level grants: clients may only supply content_id. user_id and created_at come from defaults,
-- and there is no UPDATE grant at all. content_items is read-only for clients.
revoke all on public.content_likes from anon, authenticated;
grant select, delete on public.content_likes to authenticated;
grant insert (content_id) on public.content_likes to authenticated;
revoke all on public.content_items from anon, authenticated;
grant select on public.content_items to anon, authenticated;

-- Public totals in one call. SECURITY DEFINER lets it count every row while returning only aggregates
-- (never user ids); it takes no arguments and writes nothing.
create or replace function public.like_counts()
returns table (content_id text, likes bigint)
language sql stable security definer set search_path = ''
as $$
  select l.content_id, count(*)::bigint
  from public.content_likes l
  join public.content_items c on c.id = l.content_id and c.active
  group by l.content_id
$$;
revoke all on function public.like_counts() from public, anon, authenticated;
grant execute on function public.like_counts() to anon, authenticated;
